#!/usr/bin/env bash
# Builds rs-mobile for Android and installs one static archive per ABI at
# native/core/android/src/main/jniLibs/<abi>/librs_mobile.a. The archive owns
# both the UniFFI control plane and the C ABI, matching the iOS archive layout.
#
# This script does not generate UniFFI bindings. src/native/generated and
# cpp/generated are generated by build-ios.sh on macOS and committed. If those
# bindings and librs_mobile.a come from different source revisions, the app
# fails at startup in initialize() with a checksum mismatch.
set -euo pipefail

RS_SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RS_APP_ROOT="$(cd "$RS_SCRIPT_DIR/.." && pwd)"
RS_REPO_ROOT="$(cd "$RS_APP_ROOT/.." && pwd)"

usage() {
  cat <<'EOF'
Usage: app/rust/build-android.sh [--check-only]

Builds rs-mobile static libraries for Android with cargo-ndk.

Options:
  --check-only  Verify symbols in existing archives without compiling.
  -h, --help    Show this help.

Environment:
  RS_MOBILE_PROFILE      debug or release (default: release)
  RS_ANDROID_ABIS        space-separated ABIs (default: arm64-v8a x86_64)
  RS_ANDROID_API         Android API level passed to cargo-ndk (default: 26)
  RS_MOBILE_ANDROID_OUT  output root (default: app/native/core/android/src/main/jniLibs)
  CARGO_TARGET_DIR       Cargo target directory (default: <repo>/target)
  ANDROID_NDK_HOME       NDK root; ANDROID_NDK_ROOT is used as a fallback
EOF
}

RS_CHECK_ONLY=0
while (($# > 0)); do
  case "$1" in
    --check-only) RS_CHECK_ONLY=1 ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      printf 'unknown argument: %s\n' "$1" >&2
      usage >&2
      exit 2
      ;;
  esac
  shift
done

RS_PROFILE_INPUT="${RS_MOBILE_PROFILE:-release}"
RS_PROFILE_LOWER="$(printf '%s' "$RS_PROFILE_INPUT" | tr '[:upper:]' '[:lower:]')"
case "$RS_PROFILE_LOWER" in
  debug) RS_PROFILE=debug; RS_PROFILE_ARGS=(--profile dev) ;;
  release) RS_PROFILE=release; RS_PROFILE_ARGS=(--release) ;;
  *)
    echo 'RS_MOBILE_PROFILE must be debug or release' >&2
    exit 2
    ;;
esac

RS_ABIS_INPUT="${RS_ANDROID_ABIS:-arm64-v8a x86_64}"
RS_ABIS=()
read -r -a RS_ABIS <<< "$RS_ABIS_INPUT" || true
if ((${#RS_ABIS[@]} == 0)); then
  RS_ABIS=(arm64-v8a x86_64)
fi
RS_TRIPLES=()
for RS_ABI in "${RS_ABIS[@]}"; do
  case "$RS_ABI" in
    arm64-v8a) RS_TRIPLES+=(aarch64-linux-android) ;;
    x86_64) RS_TRIPLES+=(x86_64-linux-android) ;;
    *)
      printf 'unsupported ABI: %s\n' "$RS_ABI" >&2
      exit 2
      ;;
  esac
done

RS_ANDROID_API="${RS_ANDROID_API:-26}"
RS_MOBILE_ANDROID_OUT="${RS_MOBILE_ANDROID_OUT:-$RS_APP_ROOT/native/core/android/src/main/jniLibs}"
RS_TARGET_DIR="${CARGO_TARGET_DIR:-$RS_REPO_ROOT/target}"
if [[ "$RS_TARGET_DIR" != /* ]]; then
  RS_TARGET_DIR="$RS_REPO_ROOT/$RS_TARGET_DIR"
fi
export CARGO_TARGET_DIR="$RS_TARGET_DIR"

if [[ -n "${ANDROID_NDK_HOME:-}" ]]; then
  RS_NDK="$ANDROID_NDK_HOME"
elif [[ -n "${ANDROID_NDK_ROOT:-}" ]]; then
  RS_NDK="$ANDROID_NDK_ROOT"
else
  echo 'error: set ANDROID_NDK_HOME or ANDROID_NDK_ROOT to the Android NDK root' >&2
  exit 2
fi
if [[ ! -d "$RS_NDK" ]]; then
  printf 'error: Android NDK not found at %s\n' "$RS_NDK" >&2
  exit 2
fi
# opusic-sys discovers the NDK through ANDROID_NDK_HOME specifically.
export ANDROID_NDK_HOME="$RS_NDK"

if ! cargo ndk --version >/dev/null 2>&1; then
  echo 'error: cargo-ndk is required; install it with: cargo install cargo-ndk' >&2
  exit 2
fi

if ! command -v cmake >/dev/null 2>&1; then
  RS_CMAKE_CANDIDATES=()
  if [[ -n "${ANDROID_HOME:-}" ]]; then
    for RS_CMAKE in "$ANDROID_HOME"/cmake/*/bin/cmake; do
      if [[ -x "$RS_CMAKE" ]]; then
        RS_CMAKE_CANDIDATES+=("$RS_CMAKE")
      fi
    done
  fi
  if ((${#RS_CMAKE_CANDIDATES[@]} > 0)); then
    version_gt() {
      local -a left right
      local index left_part right_part
      IFS=. read -r -a left <<< "$1"
      IFS=. read -r -a right <<< "$2"
      for index in 0 1 2 3; do
        left_part="${left[$index]:-0}"
        right_part="${right[$index]:-0}"
        if ((10#$left_part > 10#$right_part)); then
          return 0
        fi
        if ((10#$left_part < 10#$right_part)); then
          return 1
        fi
      done
      return 1
    }
    RS_LATEST_CMAKE="${RS_CMAKE_CANDIDATES[0]}"
    RS_LATEST_CMAKE_VERSION="${RS_LATEST_CMAKE#"$ANDROID_HOME"/cmake/}"
    RS_LATEST_CMAKE_VERSION="${RS_LATEST_CMAKE_VERSION%%/*}"
    for RS_CMAKE in "${RS_CMAKE_CANDIDATES[@]:1}"; do
      RS_CMAKE_VERSION="${RS_CMAKE#"$ANDROID_HOME"/cmake/}"
      RS_CMAKE_VERSION="${RS_CMAKE_VERSION%%/*}"
      if version_gt "$RS_CMAKE_VERSION" "$RS_LATEST_CMAKE_VERSION"; then
        RS_LATEST_CMAKE="$RS_CMAKE"
        RS_LATEST_CMAKE_VERSION="$RS_CMAKE_VERSION"
      fi
    done
    export PATH="$(dirname "$RS_LATEST_CMAKE"):$PATH"
  fi
fi

case "$(uname -s)" in
  Linux) RS_NDK_HOST=linux-x86_64 ;;
  Darwin) RS_NDK_HOST=darwin-x86_64 ;;
  *)
    printf 'error: unsupported NDK host: %s\n' "$(uname -s)" >&2
    exit 2
    ;;
esac
RS_LLVM_NM="$RS_NDK/toolchains/llvm/prebuilt/$RS_NDK_HOST/bin/llvm-nm"
if [[ ! -x "$RS_LLVM_NM" ]]; then
  printf 'error: llvm-nm not found at %s\n' "$RS_LLVM_NM" >&2
  exit 2
fi

RS_REQUIRED_SYMBOLS=(
  rs_now_us
  rs_session_attach
  rs_session_detach
  rs_input_pointer
  rs_input_button
  rs_input_scroll
  rs_input_touch
  rs_input_release_all
  rs_session_request_keyframe
  rs_session_report_decoded
  rs_term_attach
  rs_term_detach
  rs_term_input
  rs_term_resize
  rs_register_signer
  rs_register_secret_wrapper
  rs_raw_attach
  rs_raw_detach
  rs_raw_copy
  rs_register_secret_store
  rs_audio_open
  rs_audio_render_interleaved
  rs_audio_set_muted
  rs_audio_stats
  rs_audio_close
  uniffi_rs_mobile_fn_func_core_init
  ffi_rs_mobile_uniffi_contract_version
)

check_symbols() {
  local abi="$1"
  local archive="$2"
  local nm_output line type name
  local defined_symbols=$'\n'
  local -a fields=()
  local -a missing=()

  if [[ ! -f "$archive" ]]; then
    printf 'error: %s: archive not found: %s\n' "$abi" "$archive" >&2
    printf '  missing symbols: %s\n' "${RS_REQUIRED_SYMBOLS[*]}" >&2
    return 1
  fi
  if ! nm_output="$("$RS_LLVM_NM" --defined-only -g "$archive" 2>&1)"; then
    printf 'error: %s: llvm-nm failed for %s\n%s\n' "$abi" "$archive" "$nm_output" >&2
    return 1
  fi

  while IFS= read -r line; do
    read -r -a fields <<< "$line"
    if ((${#fields[@]} >= 2)); then
      type="${fields[${#fields[@]}-2]}"
      name="${fields[${#fields[@]}-1]}"
      case "$type" in
        T|W|I) defined_symbols+="$name"$'\n' ;;
      esac
    fi
  done <<< "$nm_output"

  for name in "${RS_REQUIRED_SYMBOLS[@]}"; do
    if [[ "$defined_symbols" != *$'\n'"$name"$'\n'* ]]; then
      missing+=("$name")
    fi
  done
  if ((${#missing[@]} > 0)); then
    printf 'error: %s: missing symbols:\n' "$abi" >&2
    printf '  %s\n' "${missing[@]}" >&2
    return 1
  fi
}

if ((RS_CHECK_ONLY == 0)); then
  RS_NDK_ARGS=(-P "$RS_ANDROID_API")
  for RS_ABI in "${RS_ABIS[@]}"; do
    RS_NDK_ARGS+=(-t "$RS_ABI")
  done
  (
    cd "$RS_REPO_ROOT"
    cargo ndk "${RS_NDK_ARGS[@]}" build --locked \
      --manifest-path "$RS_REPO_ROOT/Cargo.toml" -p rs-mobile --lib \
      "${RS_PROFILE_ARGS[@]}"
  )
fi

for RS_INDEX in "${!RS_ABIS[@]}"; do
  RS_ABI="${RS_ABIS[$RS_INDEX]}"
  RS_TRIPLE="${RS_TRIPLES[$RS_INDEX]}"
  RS_SRC="$RS_TARGET_DIR/$RS_TRIPLE/$RS_PROFILE/librs_mobile.a"
  RS_ABI_OUT="$RS_MOBILE_ANDROID_OUT/$RS_ABI"
  RS_DEST="$RS_ABI_OUT/librs_mobile.a"

  if ((RS_CHECK_ONLY == 0)); then
    if [[ ! -f "$RS_SRC" ]]; then
      printf 'error: %s: archive not produced: %s\n' "$RS_ABI" "$RS_SRC" >&2
      exit 1
    fi
    mkdir -p "$RS_ABI_OUT"
    if [[ -f "$RS_DEST" ]] && cmp -s "$RS_SRC" "$RS_DEST"; then
      printf '%s: unchanged\n' "$RS_ABI"
    else
      RS_TMP="$(mktemp "$RS_ABI_OUT/.librs_mobile.a.XXXXXX")"
      if ! cp "$RS_SRC" "$RS_TMP" || ! mv -f "$RS_TMP" "$RS_DEST"; then
        rm -f "$RS_TMP"
        printf 'error: %s: failed to install %s\n' "$RS_ABI" "$RS_DEST" >&2
        exit 1
      fi
      RS_BYTES="$(wc -c < "$RS_DEST" | tr -d '[:space:]')"
      printf '%s: updated (%s bytes)\n' "$RS_ABI" "$RS_BYTES"
    fi
  fi
done

RS_SYMBOL_CHECK_FAILED=0
for RS_INDEX in "${!RS_ABIS[@]}"; do
  RS_ABI="${RS_ABIS[$RS_INDEX]}"
  if ! check_symbols "$RS_ABI" "$RS_MOBILE_ANDROID_OUT/$RS_ABI/librs_mobile.a"; then
    RS_SYMBOL_CHECK_FAILED=1
  fi
done
if ((RS_SYMBOL_CHECK_FAILED != 0)); then
  exit 1
fi

printf 'rs-mobile android: %s; abis=%s; api=%s; out=%s\n' \
  "$RS_PROFILE" "${RS_ABIS[*]}" "$RS_ANDROID_API" "$RS_MOBILE_ANDROID_OUT"
